class TokenBucket {
    final long capacity, refill;
    long tokens, last;

    TokenBucket(long capacity, long refill, long now) {
        this.capacity = capacity;
        this.refill = refill;
        this.tokens = capacity;
        this.last = now;
    }

    boolean tryTake(long now) {
        // TODO: add refill for the seconds since last (never above capacity), then take 1 token if any.
        return true;
    }
}

class RateLimiter {
    final long capacity, refill;
    final Map<String, TokenBucket> buckets = new HashMap<>();

    RateLimiter(long capacity, long refill) {
        this.capacity = capacity;
        this.refill = refill;
    }

    TokenBucket bucket(String user, long now) {
        return buckets.computeIfAbsent(user, u -> new TokenBucket(capacity, refill, now));
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        RateLimiter limiter = null;
        for (String raw; (raw = in.readLine()) != null; ) {
            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            if (p[0].equals("LIMIT") && p.length == 3 && limiter == null) {
                limiter = new RateLimiter(Long.parseLong(p[1]), Long.parseLong(p[2]));
                out.append("limit ").append(p[1]).append(" per user, refill ").append(p[2]).append("/s\n");
            } else if (limiter == null) out.append("error: no limit set\n");
            else if (p[0].equals("REQ") && p.length == 3) {
                TokenBucket b = limiter.bucket(p[1], Long.parseLong(p[2]));
                if (b.tryTake(Long.parseLong(p[2]))) out.append("allow ").append(p[1]).append(" (").append(b.tokens).append(" left)\n");
                else out.append("deny ").append(p[1]).append("\n");
            } else out.append("error: bad command ").append(raw.trim()).append("\n");
        }
        System.out.print(out);
    }
}

